import sys
sys.path.append('storage/zetetic')
from typing import Any, Dict, Sequence
from sota_hybrid import SotaHybridV5_RegCal
import optax

def _define_hyperparameters():
    return {
        'learning_rate': 0.001, 'dropout_rate': 0.1, 'kernel_size': 7,
        'dilations': [1, 2, 4, 8, 16], 'num_transformer_layers': 2, 'num_heads': 4,
        'embed_dim': 256, 'motif_kernel_size': 5
    }

def create_optimizer(learning_rate: float = 0.001) -> optax.GradientTransformation:
    return optax.chain(
        optax.clip_by_global_norm(1.0),
        optax.adamw(learning_rate=learning_rate, weight_decay=0.01)
    )

class ModelWrapper:
    def __init__(self, **kwargs): self.network = SotaHybridV5_RegCal(**kwargs)
    def init(self, rk, di):
        from jax import random
        pk, dk = random.split(rk)
        return self.network.init({'params': pk, 'dropout': dk}, di, deterministic=True)['params']
    def apply(self, params, x, deterministic=True, rng_key=None):
        from jax import random
        if rng_key is None: rng_key = random.PRNGKey(0)
        return self.network.apply({'params': params}, x, deterministic=deterministic, rngs={'dropout': rng_key})

def create_network(hparams: Dict[str, Any]):
    return ModelWrapper(
        d_output=hparams.get("d_output"), task_type=hparams.get("task_type"),
        kernel_size=hparams.get("kernel_size"), dilations=hparams.get("dilations"),
        num_transformer_layers=hparams.get("num_transformer_layers"), num_heads=hparams.get("num_heads"),
        dropout_rate=hparams.get("dropout_rate"), embed_dim=hparams.get("embed_dim"),
        motif_kernel_size=hparams.get("motif_kernel_size")
    )
